import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`auto-repair-estimate`,heroTitle:`Generate repair estimates in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded repair notes, prices parts and labor, and builds a customer-ready estimate automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your repair order`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded repair notes, photos, or a work order. Build a complete auto repair estimate. (1) Extract the vehicle details, customer complaint, recommended repairs, diagnostics, and parts required from the uploaded files. (2) Research reasonable parts pricing and labor times for the listed repairs. (3) Group the work into urgent repairs, recommended maintenance, and optional upsells where appropriate. (4) Build a line-item estimate with parts, labor, shop supplies, taxes, and total price. (5) Flag any assumptions or items that need technician confirmation. (6) Deliver a clean repair estimate and approval summary that can be sent to the customer immediately.`,heroOverlaySteps:[`Extracting vehicle details, repair notes, and recommended work from your files`,`Researching parts pricing and labor time for each service item`,`Building a line-item estimate with urgent, recommended, and optional work`,`Customer-ready repair quote with approval summary, ready to send`],generatingSteps:[`Reading the uploaded repair order, photos, and technician notes`,`Designing an agent to price parts and estimate labor time by service item`,`Configuring estimate logic for totals, assumptions, and optional upsells`,`Preparing a customer-ready repair estimate and approval summary`],featureSectionTitle:`From work order to approved repair quote`,featureCardTitles:[`Connects to your shop workflow`,`Estimates customers can approve fast`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Sheets, docs, service notes, and internal planning tools stay connected so your estimate workflow is easy to review and hand off.`,`Line-item labor. Parts pricing. Recommended services. Approval-ready totals. Computer gives your shop an estimate that is ready for the customer conversation.`],capabilitySectionTitle:`Your service advisor, on autopilot`,capabilitySectionSubtitle:`Upload the repair order, get back a clean estimate your team can send right away.`,capabilityCards:[{title:`Work Order Analysis`,description:`Computer can extract the vehicle, complaint, diagnostics, and recommended repairs from technician notes, inspections, and uploaded paperwork.`},{title:`Parts & Labor Research`,description:`Computer can estimate parts pricing and labor time for each repair so your quote starts from a realistic baseline instead of a blank template.`},{title:`Estimate Builder`,description:`Computer can assemble urgent repairs, recommended maintenance, and optional upsells into a clear line-item estimate with totals and assumptions.`},{title:`Connect Your Tools`,description:`Computer can organize estimate drafts across sheets, docs, and internal shop workflows so approvals and follow-ups stay on track.`},{title:`Knows Your Shop Rates`,description:`Computer can remember your labor rates, markup rules, and preferred estimate format across sessions so every quote stays consistent.`},{title:`Approval Follow-Up`,description:`Computer can prepare customer summaries and next-step notes so your team can move from estimate to scheduled work with less back-and-forth.`}]});export{t as default};
